// Rate limiting: Max 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, 
  max: 100,
  message: { error: 'Too many requests from this IP, please try again later.' }
});
app.use(limiter);


// --- 2. ROUTES ---

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example of Input Validation (if you were to add a route with parameters)
// app.get('/users/:id', (req, res, next) => {
//   const userId = parseInt(req.params.id, 10);
//   if (isNaN(userId) || userId <= 0) {
//     return res.status(400).json({ error: 'Invalid user ID format. Must be a positive integer.' });
//   }
//   // Fetch user...
// });


// --- 3. ERROR HANDLING ---

// Handle 404 - Route Not Found
app.use((req, res, next) => {
  res.status(404).json({ error: `Route ${req.originalUrl} not found` });
});

// Global Error Handling Middleware
app.use((err, req, res, next) => {
  console.error('Unhandled Error:', err); // Log the error internally

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({
    status: 'error',
    message: message
  });
});

// --- 4. SERVER START ---

// Only listen if not being imported (useful for testing)
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;
